INPUTS = {'backup spool/db00.dump': 'CREATE TABLE ledger_0(id integer);\n', 'backup spool/db01.dump': 'CREATE TABLE ledger_1(id integer);\n', 'backup spool/db02.dump': 'CREATE TABLE ledger_2(id integer);\n', 'backup spool/db03.dump': 'CREATE TABLE ledger_3(id integer);\n', 'backup spool/db04.dump': 'CREATE TABLE ledger_4(id integer);\n', 'backup spool/db05.dump': 'CREATE TABLE ledger_5(id integer);\n', 'backup spool/db06.dump': 'CREATE TABLE ledger_6(id integer);\n', 'backup spool/db07.dump': 'CREATE TABLE ledger_7(id integer);\n', 'backup spool/db08.dump': 'CREATE TABLE ledger_8(id integer);\n', 'backup spool/db09.dump': 'CREATE TABLE ledger_9(id integer);\n', 'backup spool/db10.dump': 'CREATE TABLE ledger_10(id integer);\n', 'backup spool/db11.dump': 'CREATE TABLE ledger_11(id integer);\n', 'backup spool/empty.dump': '', 'backup spool/ongoing.dump.part': 'not ready\n', 'backup spool/README.txt': 'operator notes\n', 'backup spool/old/nested.dump': 'nested is excluded\n'}
import json, hashlib, re, shutil, subprocess, sys, tempfile
from pathlib import Path
SCRIPT = Path(__file__).resolve().parents[1] / 'scripts/copy_dumps.sh'
BASE = len(sys.argv) > 1 and sys.argv[1] == 'base'
def put(p, text):
    p = root / p
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')
def get(p):
    return (root / p).read_bytes().decode('utf-8')
def tree(p):
    base = root / p
    return {str(f.relative_to(base)): f.read_bytes().decode('utf-8') for f in base.rglob('*') if f.is_file()}
def run(*args, code=0):
    run.calls = getattr(run, 'calls', 0) + 1
    relative = run.calls % 2 == 0
    actual = [str(value) if relative or not (i in (0, 1)) else str(root / str(value)) for i, value in enumerate(args)]
    r = subprocess.run(['bash', str(SCRIPT), *actual], cwd=root, capture_output=True, text=True, timeout=10)
    assert r.returncode == code, (args, r.returncode, r.stdout, r.stderr)
    return r
with tempfile.TemporaryDirectory(prefix='ops-check-') as temporary:
    root = Path(temporary) / 'work area'
    root.mkdir()
    for p, text in INPUTS.items():
        put(p, text)
    before=tree('backup spool')
    put('upload area/existing.txt','keep\n');put('upload area/db00.dump','stale\n')
    run('backup spool','upload area')
    wanted={Path(p).name:v for p,v in INPUTS.items() if len(Path(p).parts)==2 and p.endswith('.dump') and v}
    assert tree('upload area') == {**wanted,'existing.txt':'keep\n'}
    assert tree('backup spool') == before
    run('backup spool','upload area');assert tree('backup spool') == before
    put('no data/a.dump','');put('no data/b.dump.part','wait\n')
    run('no data','new destination')
    assert (root/'new destination').is_dir() and tree('new destination') == {}
    put('hidden dumps/.private.dump','secret\n');put('hidden dumps/.empty.dump','')
    (root/'hidden dumps/directory.dump').mkdir()
    run('hidden dumps','hidden upload')
    assert tree('hidden upload') == {'.private.dump':'secret\n'}
    assert tree('hidden dumps') == {'.private.dump':'secret\n','.empty.dump':''}
    assert not (root/'hidden upload/directory.dump').exists()
